mapper.select:
SELECT exception_type, reference_type, reference_id, difference_amount, status
FROM t_trial_balance_exception WHERE run_id = #{runId}
ORDER BY exception_type, reference_type, reference_id

mapper.update:
UPDATE t_trial_balance_exception
SET status = #{status}, resolution_type = #{exception.resolutionType}, resolution_ref_id = #{exception.resolutionRefId},
    resolution_content_hash = #{exception.resolutionContentHash}, resolution_maker_id = #{exception.resolutionMakerId},
    resolution_checker_id = #{exception.resolutionCheckerId}, resolution_time = #{exception.resolutionTime},
    update_time = #{now}
WHERE id = #{exception.id} AND status = #{exception.status}
